mapper.update:
UPDATE game_memory_score
SET best_passed_count = #{dto.passedCount},
    best_streak = COALESCE(#{dto.bestStreak}, 0),
    max_stage = #{maxStage},
    achieved_at = NOW()
WHERE user_id = #{userId}
  AND (
    best_passed_count < #{dto.passedCount}
    OR (best_passed_count = #{dto.passedCount}
        AND best_streak < COALESCE(#{dto.bestStreak}, 0))
  )
